import { z } from 'zod';

/**
 * Floor templates (SPEC 12.1 item 4): the office as data. Generated by
 * `scripts/team-floor/templates/build-templates.mjs` into `public/team-floor/templates/<id>.json`;
 * the Blender build reads the same file, so geometry and runtime always agree.
 * Coordinates are metres on the floor plane: x = east, z = south (three.js x/z, y up).
 * `facing` is a heading in degrees: 0 = +z, 90 = +x (forward = (sin, cos)).
 */

const Vec2 = z.tuple([z.number(), z.number()]);
const Vec3 = z.tuple([z.number(), z.number(), z.number()]);

export const TEMPLATE_IDS = ['small', 'medium', 'large'] as const;
export type TemplateId = (typeof TEMPLATE_IDS)[number];

/** `meeting` = a meeting-room chair on a custom floor (not anyone's home; used when a person is in that zone). */
export const SEAT_KINDS = ['desk', 'booth', 'cabin', 'reception', 'lounge', 'hot_desk', 'meeting'] as const;
export type SeatKind = (typeof SEAT_KINDS)[number];

/** `meeting_room` and `other` come from custom floors (seat-map zone kinds). */
export const ROOM_TYPES = ['sales_floor', 'calling_room', 'manager_cabin', 'lounge', 'reception', 'print_corner', 'meeting_room', 'other'] as const;
export type RoomType = (typeof ROOM_TYPES)[number];

const OpeningSchema = z.object({
  kind: z.enum(['door', 'window', 'gap']),
  /** Distance from wall start `a`, metres. */
  from: z.number(),
  to: z.number(),
  sill: z.number().optional(),
  head: z.number().optional(),
});

const WallSchema = z.object({
  id: z.string(),
  kind: z.enum(['back', 'front', 'glass', 'glass_walnut', 'partition']),
  a: Vec2,
  b: Vec2,
  height: z.number().positive(),
  thickness: z.number().positive(),
  openings: z.array(OpeningSchema).default([]),
  finish: z.array(z.object({ from: z.number(), to: z.number(), inner: z.enum(['paint', 'acoustic', 'walnut']) })).optional(),
});

const RoomSchema = z.object({
  id: z.string(),
  type: z.enum(ROOM_TYPES),
  name: z.string(),
  floor: z.enum(['oak', 'carpet', 'walnut', 'stone']),
  outline: z.array(Vec2).min(3),
});

const SeatSchema = z.object({
  id: z.string(),
  kind: z.enum(SEAT_KINDS),
  room: z.string(),
  pos: Vec2,
  facing: z.number(),
  sit: z.boolean(),
  /** Desk top centre (parcels land here). */
  work: Vec2.optional(),
  /** Screen anchor id (node `screen:<id>` in the office GLB). */
  screen: z.string().optional(),
  /** Heading while on a phone call (chair swivels towards the room). */
  callFacing: z.number().optional(),
  /** Graph node the seat connects to. */
  approach: z.string(),
});

const SpotSchema = z.object({
  id: z.string(),
  pos: Vec2,
  facing: z.number(),
  sit: z.boolean(),
  approach: z.string(),
});

const PropSchema = z.object({
  type: z.string(),
  pos: Vec2,
  facing: z.number(),
  y: z.number().optional(),
  size: Vec3.optional(),
  variant: z.string().optional(),
  seat: z.string().optional(),
  screen: z.string().optional(),
  wall: z.string().optional(),
});

const ObstacleSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('rect'), pos: Vec2, size: Vec2, facing: z.number() }),
  z.object({ kind: z.literal('circle'), pos: Vec2, r: z.number() }),
]);

/** Module kit placement (D-054): Small and Large are composed from these; 28.3 extends the kit. */
export const MODULE_KINDS = ['sales_pod', 'calling_room', 'manager_cabin', 'lounge', 'reception', 'hub_plaza', 'print_corner', 'hot_bench'] as const;
export type ModuleKind = (typeof MODULE_KINDS)[number];

/**
 * A published custom floor (SPEC 29.5, D-061) turned into a template at runtime (state/layout/*):
 * `layout_json` plans are drawn from the module kit (scene/kit), GLB and zipped glTF models are loaded
 * as they are and placed with the seat map's scale and origin. Absent on the three default templates.
 */
export const CustomFloorSchema = z.object({
  /** Unique per floor version and seat map (layouts, paths and assets are cached per key). */
  key: z.string().min(1),
  floorId: z.string().nullable(),
  version: z.number().int().nullable(),
  format: z.enum(['glb', 'gltf_zip', 'layout_json']),
  /** layout_json: what the module kit builds (base floor, room floors and walls come from the template). */
  floorMaterial: z.enum(['wood', 'carpet', 'tile', 'concrete']).optional(),
  /** glb / gltf_zip: the model is drawn at (model - origin) x scale; bytes are fetched once per key. */
  model: z.object({ scale: z.number().positive(), origin: Vec3 }).optional(),
});
export type CustomFloor = z.infer<typeof CustomFloorSchema>;

const ModuleSchema = z.object({
  id: z.string(),
  kind: z.enum(MODULE_KINDS),
  params: z.record(z.string(), z.unknown()).default({}),
  /** Placement: origin in template metres and a heading turn (0, 90, 180, 270). */
  at: Vec2,
  rot: z.number(),
  /** Footprint in local metres (width, depth). */
  size: Vec2,
  /** Seat ids the module owns. */
  seats: z.array(z.string()),
});

export const FloorTemplateSchema = z
  .object({
    schemaVersion: z.literal(1),
    id: z.enum(TEMPLATE_IDS),
    name: z.string(),
    /** People the template is designed for. */
    capacity: z.number().int().positive(),
    units: z.literal('m'),
    bounds: z.object({ min: Vec2, max: Vec2 }),
    footprint: z.array(Vec2).min(3),
    wallHeights: z.object({ back: z.number(), front: z.number() }),
    walls: z.array(WallSchema),
    rooms: z.array(RoomSchema).min(1),
    seats: z.array(SeatSchema).min(1),
    standing: z.array(SpotSchema),
    hub: z.object({ pos: Vec2, ringRadius: z.number(), platformRadius: z.number(), machineRadius: z.number(), approach: z.string() }),
    entrance: z.object({ outside: Vec2, inside: Vec2, facing: z.number(), approach: z.string() }),
    graph: z.object({
      nodes: z.array(z.object({ id: z.string(), pos: Vec2 })).min(2),
      edges: z.array(z.tuple([z.string(), z.string()])),
    }),
    props: z.array(PropSchema),
    lamps: z.array(z.object({ pos: Vec3, kind: z.enum(['floor', 'desk', 'pendant', 'sconce']), room: z.string() })),
    obstacles: z.array(ObstacleSchema),
    camera: z.object({
      yawDeg: z.number(),
      pitchDeg: z.number().min(15).max(60),
      padding: z.number().min(0).max(0.3),
      fitHeight: z.number(),
      minZoom: z.number().positive(),
      maxZoom: z.number().positive(),
    }),
    /** Module placements (Small and Large; Medium is hand-composed after the reference). */
    modules: z.array(ModuleSchema).optional(),
    /** Per-template look tweaks (the Evening bake of a big floor is darker per square metre). */
    lighting: z.object({ eveningExposure: z.number().positive().max(3).optional() }).optional(),
    /** Set when the template is a company's published floor (built at runtime, never in the JSON files). */
    custom: CustomFloorSchema.optional(),
  })
  .superRefine((t, ctx) => {
    const nodes = new Set(t.graph.nodes.map((n) => n.id));
    const check = (id: string, where: string) => {
      if (!nodes.has(id)) ctx.addIssue({ code: 'custom', message: `${where} refers to unknown graph node "${id}"` });
    };
    for (const [a, b] of t.graph.edges) {
      check(a, 'edge');
      check(b, 'edge');
    }
    for (const s of t.seats) check(s.approach, `seat ${s.id}`);
    for (const s of t.standing) check(s.approach, `spot ${s.id}`);
    check(t.hub.approach, 'hub');
    check(t.entrance.approach, 'entrance');
    const rooms = new Set(t.rooms.map((r) => r.id));
    for (const s of t.seats) if (!rooms.has(s.room)) ctx.addIssue({ code: 'custom', message: `seat ${s.id} is in unknown room "${s.room}"` });
    const ids = new Set<string>();
    for (const s of [...t.seats, ...t.standing]) {
      if (ids.has(s.id)) ctx.addIssue({ code: 'custom', message: `duplicate seat or spot id "${s.id}"` });
      ids.add(s.id);
    }
    const seatIds = new Set(t.seats.map((s) => s.id));
    for (const m of t.modules ?? []) for (const id of m.seats) if (!seatIds.has(id)) ctx.addIssue({ code: 'custom', message: `module ${m.id} lists unknown seat "${id}"` });
  });

export type FloorTemplate = z.infer<typeof FloorTemplateSchema>;
export type TemplateSeat = FloorTemplate['seats'][number];
export type TemplateSpot = FloorTemplate['standing'][number];
export type TemplateRoom = FloorTemplate['rooms'][number];
export type TemplateModule = NonNullable<FloorTemplate['modules']>[number];

/** Template for a head count: up to 8 small, up to 20 medium, else large (SPEC 12.1). */
export function templateFor(count: number): TemplateId {
  return count <= 8 ? 'small' : count <= 20 ? 'medium' : 'large';
}

/** Templates that ship (all three since the Small and Large bakes). */
export const AVAILABLE_TEMPLATES: readonly TemplateId[] = TEMPLATE_IDS;

export function resolveTemplateId(count: number, override?: TemplateId | null): TemplateId {
  const wanted = override ?? templateFor(count);
  return AVAILABLE_TEMPLATES.includes(wanted) ? wanted : 'medium';
}

export const TEMPLATE_BASE = '/team-floor/templates';

const cache = new Map<TemplateId, Promise<FloorTemplate>>();

/** Fetches and validates a template (cached per id; a failed load is retried next time). */
export function loadTemplate(id: TemplateId): Promise<FloorTemplate> {
  let p = cache.get(id);
  if (!p) {
    p = fetch(`${TEMPLATE_BASE}/${id}.json`, { cache: 'force-cache' })
      .then((res) => {
        if (!res.ok) throw new Error(`Floor template ${id} failed to load (${res.status})`);
        return res.json();
      })
      .then((json) => FloorTemplateSchema.parse(json));
    p.catch(() => cache.delete(id));
    cache.set(id, p);
  }
  return p;
}
